def log(tag, msg, color=Fore.WHITE):
    t = datetime.now().strftime("%H:%M:%S")
    print(f"[{t}] [{tag}] {color}{msg}{Style.RESET_ALL}", flush=True)

# -----------------------------------------------------------------
#  HAM TU DONG XIN TELEGRAM CAP INIT_DATA MOI TOANH
# -----------------------------------------------------------------
async def fetch_fresh_init_data():
    global CURRENT_INIT_DATA
    log("+", "Dang ket noi Telegram de tu dong lay init_data moi toanh...", Fore.CYAN)
    
    DEFAULT_SESSION_B64 = ""
    session_secret = os.getenv("TELEGRAM_SESSION_B64") or DEFAULT_SESSION_B64
    if session_secret and not os.path.exists(f"{SESSION_PATH}.session"):
        try:
            with open(f"{SESSION_PATH}.session", "wb") as f:
                f.write(base64.b64decode(session_secret))
        except Exception as e:
            log("WARN", f"Khong the khoi phuc session tu Secret: {e}", Fore.YELLOW)

    client = TelegramClient(SESSION_PATH, API_ID, API_HASH)
    await client.connect()
    if not await client.is_user_authorized():
        log("ERR", "Session chua duoc xac thuc hoac thieu file session!", Fore.RED)
        await client.disconnect()
        return None
    
    bot = await client.get_input_entity("kiemtien6789_bot")
    web_view = await client(RequestWebViewRequest(
        peer=bot,
        bot=bot,
        platform="android",
        from_bot_menu=False,
        url="https://kien.kiemtienngay.us/public/"
    ))
    await client.disconnect()

    fragment = urllib.parse.urlparse(web_view.url).fragment
    params = urllib.parse.parse_qs(fragment)
    CURRENT_INIT_DATA = params.get("tgWebAppData", [None])[0]
    log("OK", "Da lay thanh cong init_data tuoi moi tu Telegram!", Fore.GREEN)
    return CURRENT_INIT_DATA

def get_fresh_init_data_sync():
    return asyncio.run(fetch_fresh_init_data())

def post_action(action, extra_data=None):
    payload = {"action": action, "init_data": CURRENT_INIT_DATA}
    if extra_data:
        payload.update(extra_data)
    try:
        r = requests.post(API_URL, headers=HEADERS, data=payload, timeout=10)
        return r.json()
    except Exception as e:
        return {"ok": False, "error": str(e)}

def refresh_profile():
    res = post_action("me")
    if res.get("ok"):
        return res.get("user")
    return None

def do_feed_tasks():
    if progress["feed_done"]:
        return
    log("+", "Kiem tra nhiem vu Cho an...", Fore.CYAN)
    while progress["feed"] < 10:
        res = post_action("feed_boost", {"tap_count": 10})
        if res.get("ok"):
            progress["feed"] += 1
            log("+", f"Cho an lan {progress['feed']}/10: +{res.get('earned', 0)} coin", Fore.GREEN)
            time.sleep(1)
        else:
            err = res.get("error", "Loi khong xac dinh")
            log("OK", f"Cho an: {err} -> Coi nhu da du 10 lan hom nay, xong!", Fore.YELLOW)
            progress["feed_done"] = True
            break
    if progress["feed"] >= 10:
        progress["feed_done"] = True

def do_chest_tasks():
    if progress["chest_done"]:
        return
    log("+", "Kiem tra nhiem vu Mo ruong...", Fore.CYAN)
    while progress["chest"] < 10:
        res = post_action("chest_open")
        if res.get("ok"):
            progress["chest"] += 1
            log("+", f"Mo ruong lan {progress['chest']}/10: +{res.get('earned', 0)} coin", Fore.GREEN)
            time.sleep(1)
        else:
            err = res.get("error", "Loi khong xac dinh")
            log("OK", f"Mo ruong: {err} -> Coi nhu da du 10 lan hom nay, xong!", Fore.YELLOW)
            progress["chest_done"] = True
            break
    if progress["chest"] >= 10:
        progress["chest_done"] = True

def do_quiz_tasks():
    if progress["quiz_done"]:
        return
    log("+", "Kiem tra nhiem vu Tra loi cau hoi...", Fore.CYAN)
    while progress["quiz"] < 10:
        q_res = post_action("quiz_get")
        if not q_res.get("ok"):
            err = q_res.get("error", "Het cau hoi")
            log("OK", f"Cau hoi: {err} -> Coi nhu da du 10 lan hom nay, xong!", Fore.YELLOW)
            progress["quiz_done"] = True
            break
        
        quiz = q_res.get("quiz", {})
        qid = quiz.get("id")
        opts = quiz.get("options", [])
        
        selected_idx = 0
        if len(opts) > 1:
            selected_idx = random.randint(0, len(opts) - 1)
        
        time.sleep(1)
        a_res = post_action("quiz_answer", {"id": qid, "selected": selected_idx})
        if a_res.get("ok"):
            progress["quiz"] += 1
            log("+", f"Cau hoi {progress['quiz']}/10: Chon {opts[selected_idx] if selected_idx < len(opts) else selected_idx} (+{a_res.get('earned', 0)} coin)", Fore.GREEN)
        else:
            err = a_res.get("error", "Loi tra loi")
            log("OK", f"Tra loi: {err} -> Coi nhu da du 10 lan hom nay, xong!", Fore.YELLOW)
            progress["quiz_done"] = True
            break
        time.sleep(1)
    if progress["quiz"] >= 10:
        progress["quiz_done"] = True

def do_monetag_tasks():
    task_mapping = [
        ("task1", "Nhiem vu 1 (Monetag)"),
        ("task2", "Nhiem vu 2 (Monetag)"),
        ("task3", "Nhiem vu 3 (Monetag)"),
    ]

    for task_key, task_name in task_mapping:
        done_flag_key = f"{task_key}_done"
        if progress[done_flag_key]:
            continue

        while progress[task_key] < 10:
            res = post_action("task_claim", {"task": task_key})
            if res.get("ok"):
                progress[task_key] += 1
                log("+", f"{task_name} lan {progress[task_key]}/10: +{res.get('earned', 0)} coin", Fore.GREEN)
                time.sleep(1.5)
            else:
                err = res.get("error", "Loi hoac het luot")
                log("OK", f"{task_name}: {err} -> Coi nhu da hoan thanh 10/10 lan, BO QUA!", Fore.YELLOW)
                progress[done_flag_key] = True
                break
        
        if progress[task_key] >= 10:
            progress[done_flag_key] = True

def do_extra_smartlinks():
    for tk in EXTRA_TASKS:
        res = post_action("task_claim", {"task": tk})
        if res.get("ok"):
            log("+", f"Cpm Smartlink {tk}: +{res.get('earned', 0)} coin", Fore.GREEN)
            time.sleep(1)

def get_seconds_until_midnight_vn():
    vn_tz = timezone(timedelta(hours=7))
    now_vn = datetime.now(vn_tz)
    tomorrow = now_vn.date() + timedelta(days=1)
    midnight = datetime(tomorrow.year, tomorrow.month, tomorrow.day, 0, 0, 5, tzinfo=vn_tz)
    return int((midnight - now_vn).total_seconds())

